package com.paytrace.state;
import com.paytrace.payment.PaymentState; import org.junit.jupiter.api.*; import static org.assertj.core.api.Assertions.*;
class PaymentStateMachineTest { private final PaymentStateMachine machine=new PaymentStateMachine(); @Test void acceptsFinancialLifecycle(){assertThat(machine.isValid(PaymentState.CREATED,PaymentState.INITIATED)).isTrue();assertThat(machine.isValid(PaymentState.INITIATED,PaymentState.AUTHORIZED)).isTrue();assertThat(machine.isValid(PaymentState.AUTHORIZED,PaymentState.CAPTURED)).isTrue();assertThat(machine.isValid(PaymentState.CAPTURED,PaymentState.SETTLED)).isTrue();}@Test void rejectsFinancialRegression(){assertThat(machine.isValid(PaymentState.SETTLED,PaymentState.AUTHORIZED)).isFalse();assertThatThrownBy(()->machine.transition(PaymentState.REFUNDED,PaymentState.CAPTURED)).isInstanceOf(PaymentStateMachine.InvalidPaymentTransitionException.class);}}
